import test from "node:test";
import { createHash } from "node:crypto";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { checkIdentity, parsePacket, parsePublishedPacket, parseReceipt } from "./packet.js";
import { hash, type Operation } from "./model.js";
import type { ResolvedSelection } from "./selection.js";
// Generated by Converter Python's SolvedPoseState.create, not a TS imitation.
const fixture = JSON.parse(
  readFileSync(
    new URL(
      "../../src/interactive-state/fixtures/converter-packet.json",
      import.meta.url,
    ),
    "utf8",
  ),
);
const identity = fixture.receipt.identity;
const op = {
  operationId: identity.selection.operation,
  revision: 1,
  personIndex: 0,
  candidateId: "candidate",
  stateHash: fixture.packet.stateHash,
  snapshotProof: null,
} as Operation;
const selection = {
  identity: {
    ownerBinding: identity.ownerBinding,
    source: { variant: "base" },
  },
  originalSha: identity.source.originalBvhSha256,
  sourceSha: identity.source.originalBvhSha256,
  characterId: identity.body.characterId,
  body: { resolvedBody: { assetSha256: identity.body.characterSha256 } },
  hands: null,
  scope: "full",
  camera: { projection: "orthographic" },
} as unknown as ResolvedSelection;
test("delivery requires published proof and rejects any changed canonical bytes, hash, operation or revision", () => {
  const validated = parsePacket(fixture.packet, op, selection);
  const published = { ...op, previewState: "authoritative", snapshotProof: validated.snapshotProof } as Operation;
  assert.deepEqual(parsePublishedPacket(fixture.packet, published), fixture.packet);
  for (const altered of [{ ...fixture.packet, canonicalState: fixture.packet.canonicalState + " " },
    { ...fixture.packet, stateHash: "a".repeat(64) }, { ...fixture.packet, operation: "other" },
    { ...fixture.packet, revision: 2 }]) assert.throws(() => parsePublishedPacket(altered, published));
  assert.throws(() => parsePublishedPacket(fixture.packet, { ...published, snapshotProof: null }));
  assert.throws(() => parsePublishedPacket(fixture.packet, { ...published, previewState: "solving" }));
  const canonicalState = fixture.packet.canonicalState.replace('mesh_000', 'mesh_001');
  const tampered = { ...fixture.packet, canonicalState, stateHash: createHash("sha256").update(canonicalState).digest("hex") };
  assert.throws(() => parsePublishedPacket(tampered, published));
});
test("actual Python canonical snapshot passes bounded BFF packet/receipt binding; fixture is not real FBX proof", () => {
  const validated = parsePacket(fixture.packet, op, selection);
  assert.equal(validated.payload.model.meshes[0].positions.length, 3);
  assert.equal(
    validated.snapshotProof.modelSha256,
    fixture.receipt.packetModelSha256,
  );
  const solved = { ...op, snapshotProof: validated.snapshotProof };
  assert.equal(
    parseReceipt(fixture.receipt, solved, selection).artifactSha256,
    fixture.receipt.artifactSha256,
  );
});
test("snapshot bytes, revision, owner/source/shape/hands and unsafe capabilities cannot be substituted", () => {
  for (const mutate of [
    (v: typeof fixture) => {
      v.packet.canonicalState += " ";
    },
    (v: typeof fixture) => {
      v.packet.revision = 2;
    },
    (v: typeof fixture) => {
      v.packet.stateHash = "0".repeat(64);
    },
  ]) {
    const f = structuredClone(fixture);
    mutate(f);
    assert.throws(
      () => parsePacket(f.packet, op, selection),
      /CONVERTER_INTEGRITY/,
    );
  }
  for (const changed of [
    { ...selection, originalSha: "0".repeat(64) },
    {
      ...selection,
      identity: { ...selection.identity, ownerBinding: "0".repeat(64) },
    },
    {
      ...selection,
      body: { ...selection.body, shape: { shapeSha256: "0".repeat(64) } },
    },
    {
      ...selection,
      hands: { left: "fist", right: null, library_sha256: "0".repeat(64) },
    },
  ])
    assert.throws(
      () => parsePacket(fixture.packet, op, changed as ResolvedSelection),
      /CONVERTER_INTEGRITY/,
    );
});
test("export receipt must name exact packet identity/model/runtime, current revision and original tolerances", () => {
  const valid = parsePacket(fixture.packet, op, selection),
    solved = { ...op, snapshotProof: valid.snapshotProof };
  for (const change of [
    { stateHash: "0".repeat(64) },
    { revision: 2 },
    { verified: false },
    { packetModelSha256: "0".repeat(64) },
    { runtimeRevision: "0".repeat(64) },
    { identity: { ...identity, scope: "head" } },
    {
      correspondence: {
        ...fixture.receipt.correspondence,
        positionToleranceM: 1,
      },
    },
    {
      correspondence: { ...fixture.receipt.correspondence, maxWeightError: 1 },
    },
  ])
    assert.throws(
      () => parseReceipt({ ...fixture.receipt, ...change }, solved, selection),
      /CONVERTER_INTEGRITY/,
    );
  assert.notEqual(
    hash(valid.payload.identity),
    hash({ ...valid.payload.identity, scope: "head" }),
  );
});

test("trusted default recipe rules bind unshaped bodies but cannot authorize missing explicit shape provenance", () => {
 const current = structuredClone(selection);
 current.defaultShapeRules = "standin-body-0.7.2";
 const actual = structuredClone(identity);
 actual.shape.rulesVersion = current.defaultShapeRules;
 assert.doesNotThrow(() => checkIdentity(actual, op, current));
 const wrong = structuredClone(current);
 wrong.defaultShapeRules = "another-version";
 assert.throws(() => checkIdentity(actual, op, wrong));
 const explicit = structuredClone(current);
 explicit.body.shape = { shapeSha256: null } as never;
 explicit.body.shapeSource = null;
 assert.throws(() => checkIdentity(actual, op, explicit));
});

test("unchecked hand quality is explicit while body acceptance remains mandatory", () => {
  const typed = JSON.parse(fixture.packet.canonicalState);
  typed.safety.handChecksPassed = false;
  const packet = () => { const canonicalState = JSON.stringify(typed); return { ...fixture.packet, canonicalState, stateHash: createHash("sha256").update(canonicalState).digest("hex") }; };
  const next = packet();
  const result = parsePacket(next, { ...op, stateHash: next.stateHash }, selection);
  assert.equal(result.payload.safety.handChecksPassed, false);
  typed.safety.bodyAccepted = false;
  const unsafe = packet();
  assert.throws(() => parsePacket(unsafe, { ...op, stateHash: unsafe.stateHash }, selection), /CONVERTER_INTEGRITY/);
});
